"""Visualisation: discrepancy trajectories of the three schedules.

For a chosen rate profile this script plots, for every client, the normalised
discrepancy  D_i(t)/R = (R*N_i(t) - r_i*t)/R  against time, once for the
exact-rate block schedule built from prefix sums, once for the recursive
splitting-tree schedule, and once for the online largest-lag greedy rule.
The horizontal guides show +-1 whole service and the theoretical bound of
each schedule; the vertical guides are the period boundaries, where every
curve must return to zero.
"""

from __future__ import annotations

from typing import Callable, List, Sequence, Tuple

import matplotlib.pyplot as plt

Schedule = Callable[[int], int]


def prefixes(r: Sequence[int]) -> List[int]:
    out = [0]
    for x in r:
        out.append(out[-1] + x)
    return out


def block_owner(r: Sequence[int], t: int) -> int:
    P = prefixes(r)
    s = t % P[-1]
    return max(i for i in range(len(r)) if P[i] <= s)


def bres(a: int, R: int, t: int) -> int:
    return 0 if (t * a) // R < ((t + 1) * a) // R else 1


Tree = Tuple


def balanced_tree(r: Sequence[int], base: int = 0, n: int | None = None) -> Tree:
    n = len(r) if n is None else n
    if n <= 1:
        return ("leaf", base, r[base])
    h = n // 2
    return ("node", balanced_tree(r, base, h), balanced_tree(r, base + h, n - h))


def weight(T: Tree) -> int:
    return T[2] if T[0] == "leaf" else weight(T[1]) + weight(T[2])


def depth(T: Tree) -> int:
    return 0 if T[0] == "leaf" else 1 + max(depth(T[1]), depth(T[2]))


def tree_owner(T: Tree, t: int) -> int:
    cur, time = T, t
    while cur[0] == "node":
        A, W = weight(cur[1]), weight(cur[1]) + weight(cur[2])
        m = (time * A) // W
        cur, time = (cur[1], m) if bres(A, W, time) == 0 else (cur[2], time - m)
    return cur[1]


def greedy_sequence(r: Sequence[int], T: int) -> List[int]:
    k, R = len(r), sum(r)
    N = [0] * k
    out: List[int] = []
    for t in range(T):
        best, bv = 0, r[0] * (t + 1) - R * N[0]
        for i in range(1, k):
            v = r[i] * (t + 1) - R * N[i]
            if v > bv:
                best, bv = i, v
        out.append(best)
        N[best] += 1
    return out


def trajectories(seq: Sequence[int], r: Sequence[int]) -> List[List[float]]:
    k, R = len(r), sum(r)
    N = [0] * k
    curves: List[List[float]] = [[0.0] for _ in range(k)]
    for t, s in enumerate(seq, start=1):
        N[s] += 1
        for i in range(k):
            curves[i].append((R * N[i] - r[i] * t) / R)
    return curves


def main() -> None:
    r = (3, 1, 3, 9)
    horizon = 90
    R = sum(r)
    tree = balanced_tree(list(r))
    schedules = {
        "Block schedule (prefix sums)": [block_owner(r, t) for t in range(horizon)],
        "Splitting tree (recursive Bresenham)": [tree_owner(tree, t) for t in range(horizon)],
        "Largest-lag greedy (online)": greedy_sequence(r, horizon),
    }
    bounds = {
        "Block schedule (prefix sums)": max(x * (R - x) for x in r) / R,
        "Splitting tree (recursive Bresenham)": float(depth(tree)),
        "Largest-lag greedy (online)": (len(r) - 1) * (R - 1) / R,
    }

    fig, axes = plt.subplots(1, 3, figsize=(16, 5), sharey=True)
    for ax, (name, seq) in zip(axes, schedules.items()):
        for i, curve in enumerate(trajectories(seq, r)):
            ax.plot(curve, lw=1.8, label=f"client {i} (rate {r[i]})")
        for m in range(R, horizon + 1, R):
            ax.axvline(m, color="0.85", lw=0.8, zorder=0)
        ax.axhline(0, color="0.3", lw=1)
        for v in (1, -1):
            ax.axhline(v, color="0.5", ls="--", lw=1)
        ax.axhline(bounds[name], color="darkorange", ls=":", lw=1.4)
        ax.axhline(-bounds[name], color="darkorange", ls=":", lw=1.4)
        ax.set_title(f"{name}\nbound {bounds[name]:.2f} services", fontsize=11)
        ax.set_xlabel("time slot $t$")
    axes[0].set_ylabel(r"normalised discrepancy $D_i(t)/R$")
    axes[0].legend(fontsize=9)
    fig.suptitle(
        f"Rate profile r = {r},  period R = {R}: how far each client strays from its share",
        fontsize=13,
    )
    fig.tight_layout()
    fig.savefig("discrepancy_trajectories.png", dpi=150)
    print("wrote discrepancy_trajectories.png")


if __name__ == "__main__":
    main()
